insert into CHB_PRODUCTS_DEAL_SUB ( REGIST_SEQNO, STATUS_BATCH, CUST_CONTRACT_NO, CUST_NAME, ACCOUNT, FUND_ACC, FIN_ACC, EQUITY_CONF_DATE, CCY, SHARES, AMOUNT, AMOUNT_CNY, FEE_AMT, BUSI_TYPE, CHANNEL, BUSI_SEQNO, ORG_ID, BANK_MARK, DATE_STATUS, GROUP_ID, STATUS, CREATE_USER, ORG_CODE, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) SELECT A.REGIST_SEQNO,A.STATUS_BATCH,A.CUST_CONTRACT_NO, A.CUST_NAME,A.ACCOUNT,A.FUND_ACC, A.FIN_ACC,A.EQUITY_CONF_DATE,A.CCY, A.SHARES,A.AMOUNT,A.AMOUNT_CNY, A.FEE_AMT,A.BUSI_TYPE,A.CHANNEL, A.BUSI_SEQNO,A.ORG_ID,A.BANK_MARK, A.DATE_STATUS,A.GROUP_ID,A.STATUS, A.CREATE_USER,A.ORG_CODE,A.CREATE_DEPT, A.CREATE_TIME,A.UPDATE_USER,A.UPDATE_TIME FROM (
SELECT #{item.registSeqno,jdbcType=VARCHAR} AS REGIST_SEQNO, #{item.statusBatch,jdbcType=VARCHAR} AS STATUS_BATCH, #{item.custContractNo,jdbcType=VARCHAR} AS CUST_CONTRACT_NO, #{item.custName,jdbcType=VARCHAR} AS CUST_NAME, #{item.account,jdbcType=VARCHAR} AS ACCOUNT, #{item.fundAcc,jdbcType=VARCHAR} AS FUND_ACC, #{item.finAcc,jdbcType=VARCHAR} AS FIN_ACC, #{item.equityConfDate,jdbcType=DATE} AS EQUITY_CONF_DATE, #{item.ccy,jdbcType=VARCHAR} AS CCY, #{item.shares,jdbcType=DECIMAL} AS SHARES, #{item.amount,jdbcType=DECIMAL} AS AMOUNT, #{item.amountCny,jdbcType=DECIMAL} AS AMOUNT_CNY, #{item.feeAmt,jdbcType=DECIMAL} AS FEE_AMT, #{item.busiType,jdbcType=VARCHAR} AS BUSI_TYPE, #{item.channel,jdbcType=VARCHAR} AS CHANNEL, #{item.busiSeqno,jdbcType=VARCHAR} AS BUSI_SEQNO, #{item.orgId,jdbcType=VARCHAR} AS ORG_ID, #{item.bankMark,jdbcType=VARCHAR} AS BANK_MARK, #{item.dateStatus,jdbcType=DATE} AS DATE_STATUS, #{item.groupId,jdbcType=VARCHAR} AS GROUP_ID, #{item.status,jdbcType=VARCHAR} AS STATUS, #{item.createUser,jdbcType=VARCHAR} AS CREATE_USER, #{item.orgCode,jdbcType=VARCHAR} AS ORG_CODE, #{item.createDept,jdbcType=VARCHAR} AS CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} AS CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} AS UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} AS UPDATE_TIME FROM dual
) A
